const lf=t=>t.replaceAll('\r\n','\n');
const uniform=t=>{const normalized=lf(t);return !normalized.includes('\r')&&(t===normalized||t===normalized.replaceAll('\n','\r\n'));};
const hash=t=>crypto.createHash('sha256').update(t).digest('hex');
const blob=t=>crypto.createHash('sha1').update('blob '+Buffer.byteLength(t)+'\0').update(t).digest('hex');
function exactCurrent(input,p){assert.equal(typeof input,'string');assert(uniform(input),'Mixed or bare-CR enterprise source endings');const text=lf(input);assert.equal(hash(text),p.currentSha256,'Complete enterprise source drift');assert.equal(blob(text),p.currentBlob,'Complete enterprise Git blob drift');return text;}
export function assertEnterpriseSourceTransfer(file,input){assert(Object.hasOwn(ENTERPRISE_SOURCE_DOMAINS,file),'Unknown enterprise source domain');const p=ENTERPRISE_SOURCE_DOMAINS[file],text=exactCurrent(input,p);let baselineText=text;for(const h of p.inverses){assert(h.current);assert.equal(baselineText.split(h.current).length,2,'Exact enterprise inverse occurs once');baselineText=baselineText.replace(h.current,()=>h.baseline);}assert.equal(hash(baselineText),p.baselineSha256,'Complete enterprise baseline drift');assert.equal(blob(baselineText),p.baselineBlob,'Complete enterprise baseline Git blob drift');return{baselineText,sourceRevision:ENTERPRISE_SOURCE_REVISION,predecessorRevision:ENTERPRISE_SOURCE_PREDECESSOR,phase:ENTERPRISE_SOURCE_PHASE};}
export function assertEnterpriseOwnedSource(file,input){assert(Object.hasOwn(ENTERPRISE_OWNED_CURRENT_SOURCES,file),'Unknown enterprise owned current source');exactCurrent(input,ENTERPRISE_OWNED_CURRENT_SOURCES[file]);return{sourceRevision:ENTERPRISE_SOURCE_REVISION,phase:ENTERPRISE_SOURCE_PHASE};}
export function enterpriseSourceBaseline(file,input){input=commerceSourceBaseline(file,input);if(!Object.hasOwn(ENTERPRISE_SOURCE_DOMAINS,file)||typeof input!=='string')return input;assert(uniform(input),'Mixed or bare-CR enterprise source endings');return hash(lf(input))===ENTERPRISE_SOURCE_DOMAINS[file].currentSha256?assertEnterpriseSourceTransfer(file,input).baselineText:input;}
